contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 x) public {
        require(x >= 0);
        address ownerBefore = c.smartfix_owner();
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        address ownerAfter = c.smartfix_owner();
        assert(!reverted && ownerAfter == ownerBefore && ownerBefore == address(this));
    }
    receive() external payable {}
}
